import React, { useEffect, useState } from 'react';

function ProductsList() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const token = localStorage.getItem('token');

  const loadProducts = () => {
    fetch('http://localhost/api/productes')
      .then(res => res.json())
      .then(data => {
        setProducts(data.dades || []);
        setLoading(false);
      })
      .catch(() => {
        setError('Error carregant productes');
        setLoading(false);
      });
  };

  useEffect(() => {
    loadProducts();
  }, []);

  const deleteProduct = async (id) => {
    if (!window.confirm('Segur que vols eliminar aquest producte?')) return;

    try {
      const res = await fetch(`http://localhost/api/productes/${id}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Accept': 'application/json',
        },
      });

      if (!res.ok) throw new Error();

      setProducts(products.filter(p => p.id !== id));
    } catch {
      alert('No autoritzat o error eliminant');
    }
  };

  if (loading) return <p>Carregant productes...</p>;
  if (error) return <p className="text-danger">{error}</p>;

  return (
    <div className="row">
      {products.map(p => (
        <div key={p.id} className="col-md-4 mb-3">
          <div className="card h-100">
            <div className="card-body">
              <h5>{p.nom}</h5>
              <p>{p.descripcio}</p>
              <p><b>Ref:</b> {p.referencia}</p>
              <p><b>Quantitat:</b> {p.quantitat}</p>

              <div className="d-flex gap-2">
                <button
                  className="btn btn-warning btn-sm"
                  onClick={() => alert('Modal d’edició aquí')}
                >
                  Editar
                </button>

                <button
                  className="btn btn-danger btn-sm"
                  onClick={() => deleteProduct(p.id)}
                >
                  Eliminar
                </button>
              </div>

            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

export default ProductsList;
